let D, page='overview', selectedAsset='', busy=false, reportMonth='', reportAnalytics=null, reportTab='department', assetStatus='', assetQuery='', typeFilter='', departmentFilter='', locationFilter='', auditSelected='', auditFilter='all', auditQuery='', catalogTab='types', lastDocumentId='', lastDocumentHtml='', afterLoadAsset='', requestSequence=0, saleSequence=0;
const $=id=>document.getElementById(id);
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',box:'M3 7l9-4 9 4-9 4-9-4z M3 7v10l9 4 9-4V7 M12 11v10',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',user:'M20 21v-2a7 7 0 0 0-14 0v2 M13 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',search:'M21 21l-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',back:'M19 12H5 M11 6l-6 6 6 6',down:'M6 9l6 6 6-6',chevron:'M9 5l7 7-7 7',check:'M5 12l4 4L19 6',clipboard:'M9 5H5v16h14V5h-4 M9 3h6v5H9z M8 14l3 3 5-6',chart:'M4 20h17 M7 16V9 M12 16V4 M17 16v-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3l-1 3-3 1-2 5 2 5 3 1 1 3h6l1-3 3-1 2-5-2-5-3-1-1-3z',clock:'M12 8v5l3 2 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',alert:'M12 3L2 21h20L12 3z M12 9v5 M12 17v1',tool:'M14 6a5 5 0 0 0-6 6L3 17a3 3 0 0 0 4 4l5-5a5 5 0 0 0 6-6l-4 2-3-3 3-3z',return:'M9 4L4 9l5 5 M4 9h11a5 5 0 0 1 0 10h-3',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 12-1l2 3 M18 17a7 7 0 0 1-12 1l-2-3',edit:'M16 3l5 5-12 12-6 1 1-6L16 3z M13 6l5 5',print:'M6 8V3h12v5 M6 17H3V8h18v9h-3 M6 14h12v7H6z M17 11h1',copy:'M8 8h13v13H8z M16 8V3H3v13h5',image:'M3 3h18v18H3z M3 16l5-5 4 4 3-3 6 6 M15 7h1',close:'M6 6l12 12 M18 6L6 18',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',menu:'M4 6h16 M4 12h16 M4 18h16',mail:'M3 5h18v14H3z M3 5l9 8 9-8',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4z',external:'M14 3h7v7 M21 3L10 14 M10 3H3v18h18v-7',file:'M14 2H4v20h16V8l-6-6z M14 2v6h6 M8 13h8 M8 17h6',monitor:'M3 3h18v14H3z M8 21h8 M12 17v4'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;}
function boxIcon(name,color=''){return `<span class="iconbox ${color}">${icon(name)}</span>`;}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>Number(v||0).toLocaleString('vi-VN')+' đ';
const compactMoney=v=>Math.abs(Number(v||0))>=1000000?(Number(v)/1000000).toLocaleString('vi-VN',{maximumFractionDigits:1})+' tr':money(v);
const num=v=>Number(v||0).toLocaleString('vi-VN',{maximumFractionDigits:3});
const displayDate=v=>v?String(v).slice(0,10).split('-').reverse().join('/'):'—';
const date=()=>D?.today||new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Ho_Chi_Minh'}).format(new Date());
const names={TRONG_KHO:'Trong kho',DANG_DUNG:'Đang sử dụng',DANG_MUON:'Đang cho mượn',DANG_SUA:'Đang sửa chữa',HONG:'Hỏng',THAT_LAC:'Thất lạc',THANH_LY:'Đã thanh lý'};
const actions={CAP_PHAT:'Cấp phát',DIEU_CHUYEN:'Điều chuyển',THU_HOI:'Thu hồi',THANH_LY:'Thanh lý',CHO_MUON:'Cho mượn',TRA_MUON:'Trả tài sản',BAO_HONG:'Báo hỏng',BAO_MAT:'Báo thất lạc',SUA_CHUA:'Gửi sửa chữa',HOAN_TAT_SUA:'Hoàn tất sửa chữa',NHAP_VT:'Nhập kho',XUAT_VT:'Xuất dùng'};
const statusColors={DANG_DUNG:'#6fb59c',TRONG_KHO:'#8c78d8',DANG_MUON:'#729cca',DANG_SUA:'#dfc26b',HONG:'#db8a9a',THAT_LAC:'#b4a4bb',THANH_LY:'#c5cad5'};
const statusClass={DANG_DUNG:'green',TRONG_KHO:'',DANG_MUON:'blue',DANG_SUA:'orange',HONG:'red',THAT_LAC:'red',THANH_LY:''};
const actionIcons={CAP_PHAT:'arrow',DIEU_CHUYEN:'return',CHO_MUON:'clock',TRA_MUON:'return',THU_HOI:'return',THANH_LY:'trash',SUA_CHUA:'tool',HOAN_TAT_SUA:'check',BAO_HONG:'alert',BAO_MAT:'alert',NHAP_VT:'box',XUAT_VT:'arrow'};
const navItems=[['overview','Bảng điều khiển','grid'],['assets','Tài sản','monitor'],['issue','Cấp phát & Mượn trả','arrow'],['audit','Kiểm kê','clipboard'],['stock','Kho vật tư','box'],['report','Báo cáo','chart'],['employees','Nhân viên','users'],['catalog','Danh mục','grid'],['settings','Cài đặt','settings']];
let toastTimer;
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').style.display='block';toastTimer=setTimeout(()=>$('toast').style.display='none',5500);}
function setBusy(value){busy=value;document.querySelectorAll('button').forEach(b=>{if(value){b.dataset.previousDisabled=String(b.disabled);b.disabled=true;}else if(b.dataset.previousDisabled!==undefined){b.disabled=b.dataset.previousDisabled==='true';delete b.dataset.previousDisabled;}});}
function rpc(fn,args=[]){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Google chưa phản hồi '+fn+' sau 90 giây. Kiểm tra mục Lần thực thi trong Apps Script rồi thử lại.')),90000);const success=value=>{clearTimeout(timer);resolve(value);},failure=error=>{clearTimeout(timer);reject(error);};try{google.script.run.withSuccessHandler(success).withFailureHandler(failure)[fn](...args);}catch(e){failure(e);}});}
async function call(fn,args,done){try{const r=await rpc(fn,args);if(done)done(r);return r;}catch(e){reportError(e);}}
function reportError(e){const message=e.message||String(e);setBusy(false);if($('modal').open){$('formError').textContent=message;$('formError').style.display='block';}else toast(message);}
async function load(){try{const sequence=++requestSequence;const d=await rpc('getData');if(sequence!==requestSequence)return;D=d;reportMonth=D.month;reportAnalytics=null;if(afterLoadAsset){selectedAsset=afterLoadAsset;page='detail';afterLoadAsset='';}render();window.__assetReady=true;clearTimeout(window.__assetLoadingTimer);}catch(e){$('content').innerHTML=`<div class="panel error-screen"><h2>Chưa kết nối được dữ liệu</h2><p>${esc(e.message||e)}</p><p class="sub">Nếu vừa cập nhật V2, mở Apps Script và chạy setup để thêm cột mới, giữ dữ liệu cũ.</p><button onclick="load()">Thử lại</button></div>`;}}
function go(target){page=target;toggleMenu(false);render();window.scrollTo({top:0});}
function toggleMenu(value){const open=value===undefined?!$('sidebar').classList.contains('open'):value;$('sidebar').classList.toggle('open',open);$('overlay').classList.toggle('open',open);}
function employee(id){return (D.employees.find(e=>e.id===id)||{}).name||'';}
function typeName(id){return (D.types.find(t=>t.id===id)||{}).name||id;}
function statusBadge(status){return `<span class="badge ${statusClass[status]||''}"><span class="dot" style="width:4px;height:4px;background:${statusColors[status]||'#aaa'}"></span>${esc(names[status]||status)}</span>`;}
function stat(label,value,hint,ic='box',color=''){return `<div class="stat"><div><div class="label">${esc(label)}</div><div class="value">${esc(value)}</div><div class="hint">${esc(hint||'')}</div></div>${boxIcon(ic,color)}</div>`;}
function table(headers,lines){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${lines.length?lines.join(''):`<tr><td colspan="${headers.length}"><div class="empty">Không có dữ liệu phù hợp</div></td></tr>`}</tbody></table></div>`;}
function head(title,subtitle,actionsHtml='',crumb=''){ $('title').textContent=title;$('subtitle').textContent=subtitle;$('pageActions').innerHTML=actionsHtml;$('breadcrumb').textContent=crumb||'Tổng quan / '+title;}
function render(){if(!D)return;document.body.dataset.page=page;$('brandIcon').innerHTML=icon('box');$('menuButton').innerHTML=icon('menu');$('searchIcon').innerHTML=icon('search');$('refreshButton').innerHTML=icon('refresh');$('createGlobal').innerHTML=icon('plus')+'<span class="create-label">Tạo mới</span>';$('closeModal').innerHTML=icon('close');$('businessLabel').textContent=D.settings.businessName;$('topDate').textContent=new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date());
 $('nav').innerHTML=navItems.map(([id,title,ic])=>`<button class="${page===id||(page==='detail'&&id==='assets')?'active':''}" onclick="go('${id}')">${icon(ic)}${title}${id==='assets'?`<span class="nav-count">${D.assets.filter(a=>a.kind!=='VT').length}</span>`:''}</button>`).join('');
 const views={overview:overviewView,assets:assetsView,detail:detailView,issue:issueView,audit:auditView,stock:stockView,report:reportView,employees:employeesView,catalog:catalogView,settings:settingsView};(views[page]||overviewView)();}
function chart(bins,showValues=false){const max=Math.max(1,...bins.map(b=>b.value));return `<div class="chart">${bins.map(b=>`<div class="chart-col" title="${esc(b.label)}: ${money(b.value)}">${showValues?`<div class="chart-value">${esc(compactMoney(b.value))}</div>`:''}<div class="chart-bar-area"><div class="chart-bar" style="height:${Math.max(1,128*b.value/max)}px"></div></div><div class="chart-label">${esc(b.label.length===7?b.label.slice(5):b.label)}</div></div>`).join('')}</div>`;}
function donut(assets){const entries=Object.keys(names).map(s=>({s,count:assets.filter(a=>a.status===s).length})),total=assets.length;let at=0;const stops=entries.map(x=>{const start=at;at+=100*x.count/Math.max(1,total);return `${statusColors[x.s]} ${start}% ${at}%`;}).join(',');return `<div class="donut-area"><div class="donut" role="img" aria-label="${total} tài sản theo trạng thái" style="background:${total?'conic-gradient('+stops+')':'#efedf4'}"><div class="donut-hole"><b>${total}</b><small>tài sản</small></div></div><div class="legend">${entries.map(x=>`<div class="legend-row"><i class="dot" style="background:${statusColors[x.s]}"></i>${names[x.s]}<b>${x.count}</b></div>`).join('')}</div></div>`;}
const alertTitles={loan:'Mượn quá hạn chưa trả',maintenanceLate:'Quá hạn bảo trì',maintenanceSoon:'Bảo trì trong 30 ngày tới',warranty:'Sắp hết bảo hành',broken:'Hỏng đang chờ sửa chữa',lost:'Thất lạc',noOwner:'Thiếu người / bộ phận giữ tài sản'};
function overviewView(){const assets=D.assets.filter(a=>a.kind!=='VT'),active=assets.filter(a=>a.status!=='THANH_LY'),alerts=D.alerts||[];head('Bảng điều khiển','Tổng quan vòng đời tài sản và những việc cần xử lý',`<button onclick="transactionForm('CAP_PHAT')">${icon('arrow')} Cấp phát</button><button class="primary" onclick="assetForm()">${icon('plus')} Thêm tài sản</button>`,'Tổng quan');
 $('content').innerHTML=`<div class="stats">${stat('Đang quản lý',active.length,'Tài sản hiện có','box')}${stat('Đang sử dụng',active.filter(a=>a.status==='DANG_DUNG').length,'Đã cấp cho người dùng','user','green')}${stat('Trong kho',active.filter(a=>a.status==='TRONG_KHO').length,'Sẵn sàng cấp phát','box','blue')}${stat('Có vấn đề',active.filter(a=>['HONG','THAT_LAC','DANG_SUA'].includes(a.status)).length,'Hỏng, thất lạc, sửa chữa','alert','red')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h3>Việc cần xử lý</h3><small>Bấm vào từng dòng để xem danh sách</small></div></div>${Object.keys(alertTitles).map((key,i)=>{const count=key==='noOwner'?active.filter(a=>a.status==='DANG_DUNG'&&!a.employeeId&&!a.department).length:alerts.filter(a=>a.type===key).length;return `<div class="alert-row">${boxIcon(i<2?'clock':i===3?'shield':i===4?'tool':'alert',i<2?'red':i<4?'orange':'')}<button class="link alert-text" onclick="showAlert('${key}')">${esc(key==='maintenanceSoon'?'Bảo trì trong '+D.settings.reminderDays+' ngày tới':alertTitles[key])}<small>${i===0?'Nhắc người mượn trả tài sản':i===3?'Kiểm tra thời hạn bảo hành':'Theo dõi và cập nhật xử lý'}</small></button><span class="alert-number">${count}</span>${icon('chevron')}</div>`;}).join('')}</section><section class="panel"><div class="panel-heading"><div><h3>Tình trạng tài sản</h3><small>Phân bổ theo trạng thái hiện tại</small></div></div>${donut(assets)}</section><section class="panel"><div class="panel-heading"><div><h3>Chi phí bảo trì 12 tháng</h3><small>Tổng chi phí sửa chữa, bảo trì đã ghi nhận</small></div><button class="link" onclick="reportTab='maintenance';go('report')">Xem báo cáo</button></div>${chart(maintenanceBins())}</section><section class="panel"><div class="panel-heading"><div><h3>Hoạt động gần đây</h3><small>Lịch sử thay đổi và giao dịch</small></div></div>${timeline(D.transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||'')).slice(0,4))}</section></div>`;}
function maintenanceBins(analytics=D.analytics){return analytics.monthly.map(b=>({label:b.label,value:D.maintenance.filter(m=>m.date.startsWith(b.label)).reduce((s,m)=>s+Number(m.cost),0)}));}
function timeline(tx){return `<div class="timeline">${tx.length?tx.map(t=>`<div class="event ${['NHAP_VT','THU_HOI','TRA_MUON'].includes(t.type)?'green':t.type==='THANH_LY'?'red':''}"><small>${displayDate(t.date)}</small><b>${esc(actions[t.type]||t.type)}</b><p>${esc(t.assetName)}${t.employeeName?' · '+esc(t.employeeName):''}</p><button class="link" onclick="documentFor('${t.requestId||t.id}')">${icon('file')} Biên bản ${esc((t.requestId||t.id).slice(0,12))}</button></div>`).join(''):'<div class="empty">Chưa có hoạt động</div>'}</div>`;}
function showAlert(key){if(key==='noOwner'){const list=D.assets.filter(a=>a.status==='DANG_DUNG'&&!a.employeeId&&!a.department);head(alertTitles[key],list.length+' tài sản cần xem',`<button onclick="go('overview')">Tổng quan</button>`);$('content').innerHTML='<div class="panel">'+assetTable(list)+'</div>';return;}const ids=(D.alerts||[]).filter(a=>a.type===key).map(a=>a.assetId);head(alertTitles[key],ids.length+' tài sản cần xem',`<button onclick="go('overview')">${icon('back')} Tổng quan</button>`);$('content').innerHTML=`<div class="panel">${assetTable(D.assets.filter(a=>ids.includes(a.id)))}</div>`;}
function filteredAssets(includeMaterials=false){const q=assetQuery.toLocaleLowerCase('vi');return D.assets.filter(a=>(includeMaterials||a.kind!=='VT')&&(!assetStatus||a.status===assetStatus)&&(!typeFilter||a.kind===typeFilter)&&(!departmentFilter||a.department===departmentFilter)&&(!locationFilter||a.location===locationFilter)&&[a.code,a.name,a.location,a.department,employee(a.employeeId)].join(' ').toLocaleLowerCase('vi').includes(q));}
function assetTable(list){return table(['Tài sản','Loại tài sản','Người sử dụng','Bộ phận / Vị trí','Ngày mua','Nguyên giá','Trạng thái',''],list.map(a=>`<tr><td><div class="asset-cell">${boxIcon(a.kind==='MI'?'monitor':'box')}<div><button class="link asset-name" onclick="detail('${a.id}')">${esc(a.name)}</button><span class="code">${esc(a.code)}</span></div></div></td><td>${esc(typeName(a.kind))}</td><td>${esc(employee(a.employeeId)||'—')}</td><td>${esc(a.department||'—')}<span class="code">${esc(a.location)}</span></td><td>${displayDate(a.purchaseDate)}</td><td>${money(a.price)}</td><td>${statusBadge(a.status)}</td><td class="table-actions"><button onclick="assetForm('${a.id}')" aria-label="Sửa ${esc(a.name)}">${icon('edit')}</button><button onclick="detail('${a.id}')" aria-label="Xem chi tiết">${icon('chevron')}</button></td></tr>`));}
function optionTags(items,value='',first='Tất cả'){return `<option value="">${esc(first)}</option>`+items.map(x=>`<option value="${esc(x[0])}" ${String(value)===String(x[0])?'selected':''}>${esc(x[1])}</option>`).join('');}
function assetsView(){head('Tài sản','Quản lý thông tin, cấp phát và toàn bộ vòng đời tài sản',`<button onclick="exportAssets(true)">${icon('download')} Xuất Excel</button><button class="desktop-only" onclick="exportAssets()">CSV</button><button class="primary" onclick="assetForm()">${icon('plus')} Thêm tài sản</button>`);$('content').innerHTML=`<div class="tabs">${[['','Tất cả'],...Object.entries(names)].map(([s,n])=>`<button class="${assetStatus===s?'active':''}" onclick="assetStatus='${s}';render()">${n} <span class="count">${D.assets.filter(a=>a.kind!=='VT'&&(!s||a.status===s)).length}</span></button>`).join('')}</div><section class="panel"><div class="filters"><div class="search-field">${icon('search')}<input value="${esc(assetQuery)}" oninput="assetQuery=this.value;updateAssetTable()" placeholder="Tìm mã, tên, người dùng, vị trí…" aria-label="Tìm trong danh sách"></div><select aria-label="Lọc loại" onchange="typeFilter=this.value;updateAssetTable()">${optionTags(D.types.filter(t=>t.id!=='VT').map(t=>[t.id,t.name]),typeFilter,'Tất cả loại')}</select><select aria-label="Lọc bộ phận" onchange="departmentFilter=this.value;updateAssetTable()">${optionTags(D.departments.map(t=>[t.name,t.name]),departmentFilter,'Mọi bộ phận')}</select><select aria-label="Lọc vị trí" onchange="locationFilter=this.value;updateAssetTable()">${optionTags(D.locations.map(t=>[t.name,t.name]),locationFilter,'Mọi vị trí')}</select></div><div id="assetTable">${assetTable(filteredAssets())}</div><div class="table-footer"><span id="assetCount">${filteredAssets().length} tài sản</span><span>Chọn tên tài sản để xem chi tiết</span></div></section>`;}
function updateAssetTable(){$('assetTable').innerHTML=assetTable(filteredAssets());$('assetCount').textContent=filteredAssets().length+' tài sản';}
function detail(id){selectedAsset=id;go('detail');}
function info(label,value,accent=false){return `<div class="info-item"><dt>${esc(label)}</dt><dd class="${accent?'accent':''}">${esc(value||'Chưa có')}</dd></div>`;}
function assetDep(a,month=D.month){if(a.kind==='VT')return {monthly:0,accumulated:0,remaining:Number(a.price),elapsed:0};const sale=D.transactions.find(t=>t.assetId===a.id&&t.type==='THANH_LY');const end=sale&&sale.date.slice(0,7)<month?sale.date.slice(0,7):month;const [y,m]=end.split('-').map(Number),[sy,sm]=a.purchaseDate.split('-').map(Number),life=Number(a.months),elapsed=Math.max(0,Math.min(life,(y-sy)*12+m-sm+1)),accumulated=Math.min(Number(a.price),Math.round(Number(a.price)*elapsed/life));return {monthly:Math.round(Number(a.price)/life),accumulated,remaining:Number(a.price)-accumulated,elapsed};}
function assetActions(a){if(a.kind==='VT')return [['NHAP_VT','Nhập vật tư'],['XUAT_VT','Xuất dùng vật tư']];const rules={CAP_PHAT:['TRONG_KHO'],CHO_MUON:['TRONG_KHO'],DIEU_CHUYEN:['DANG_DUNG'],THU_HOI:['DANG_DUNG'],TRA_MUON:['DANG_MUON'],SUA_CHUA:['TRONG_KHO','DANG_DUNG','HONG'],HOAN_TAT_SUA:['DANG_SUA'],BAO_HONG:['TRONG_KHO','DANG_DUNG','DANG_MUON'],BAO_MAT:['TRONG_KHO','DANG_DUNG','DANG_MUON','HONG'],THANH_LY:['TRONG_KHO','DANG_DUNG','HONG','THAT_LAC','DANG_SUA']};return Object.keys(rules).filter(k=>rules[k].includes(a.status)).map(k=>[k,({CAP_PHAT:'Cấp phát cho nhân viên',CHO_MUON:'Cho mượn tài sản',DIEU_CHUYEN:'Điều chuyển nội bộ',THU_HOI:'Thu hồi về kho',THANH_LY:'Thanh lý'})[k]||actions[k]]);}
function detailView(){const a=D.assets.find(a=>a.id===selectedAsset);if(!a){head('Không tìm thấy tài sản','Mã QR hoặc tài sản không tồn tại',`<button onclick="go('assets')">Quay lại</button>`);$('content').innerHTML='';return;}const dep=assetDep(a),tx=D.transactions.filter(t=>t.assetId===a.id).slice().reverse(),events=[...tx.map(t=>({date:t.createdAt||t.date,html:timeline([t])})),...D.auditLines.filter(l=>l.assetId===a.id&&l.result!=='CHUA_KIEM').map(l=>({date:l.updatedAt,html:`<div class="timeline"><div class="event green"><small>${displayDate(l.updatedAt)}</small><b>Kiểm kê</b><p>${esc(({CO_MAT:'Có mặt',THIEU:'Lệch số lượng',HONG:'Hỏng',SAI_VI_TRI:'Sai vị trí'})[l.result])} · ${esc(l.note)}</p><button class="link" onclick="documentFor('${l.auditId}')">Biên bản kiểm kê</button></div></div>`})),...D.history.filter(h=>h.assetId===a.id).map(h=>({date:h.createdAt,html:`<div class="timeline"><div class="event"><small>${esc(h.createdAt.replace('T',' '))}</small><b>${h.action==='ANH'?'Cập nhật ảnh':'Cập nhật thông tin'}</b><p>${esc(h.actor)}</p>${h.action==='SUA'?`<details><summary class="link">Xem thay đổi</summary><p>${changedFields(h)}</p></details>`:''}</div></div>`})),...D.maintenance.filter(m=>m.assetId===a.id).map(m=>({date:m.createdAt,html:`<div class="timeline"><div class="event green"><small>${displayDate(m.date)}</small><b>Bảo trì / sửa chữa</b><p>${esc(m.content)} · ${money(m.cost)}</p><button class="link" onclick="documentFor('${m.requestId||m.id}')">${icon('file')} Biên bản</button></div></div>`}))].sort((x,y)=>y.date.localeCompare(x.date));
 head(a.name,`${a.code} · ${typeName(a.kind)}${a.sample==='true'?' · Dữ liệu mẫu':''}`,`<button onclick="go('assets')">${icon('back')} Quay lại</button><button onclick="assetForm('${a.id}')">${icon('edit')} Sửa</button>${a.status==='TRONG_KHO'&&a.kind!=='VT'?`<button class="primary" onclick="transactionForm('CAP_PHAT','${a.id}')">${icon('arrow')} Cấp phát</button>`:''}`,'Tài sản / '+a.name);
 $('content').innerHTML=`<div class="detail-grid"><div><section class="panel"><div class="panel-heading"><h3>Thông tin tài sản</h3>${statusBadge(a.status)}</div><dl class="info-grid">${info('Mã tài sản',a.code)}${info('Loại tài sản',typeName(a.kind))}${info('Thương hiệu',a.brand)}${info('Model',a.model)}${info('Số serial',a.serial)}${info('Nhà cung cấp',a.supplier)}${info('Ngày mua',displayDate(a.purchaseDate)+' '+(a.purchaseTime||''))}${info('Hết bảo hành',a.warrantyDate?displayDate(a.warrantyDate):'Chưa có')}${info('Bảo trì tiếp theo',a.nextMaintenance?displayDate(a.nextMaintenance):'Chưa có')}${info('Người sử dụng',employee(a.employeeId),true)}${info('Bộ phận',a.department)}${info('Vị trí',a.location)}${info('Tình trạng',a.condition)}${a.status==='DANG_MUON'?info('Hạn trả',displayDate(a.loanDueDate)):''}${a.note?'<div class="wide">'+info('Ghi chú',a.note)+'</div>':''}</dl></section>${a.kind!=='VT'?`<section class="panel"><h3>Khấu hao</h3><small>Đường thẳng theo tháng · tính đủ tháng mua</small><div class="depreciation-metrics"><div><small>Nguyên giá</small><b>${money(a.price)}</b></div><div><small>Khấu hao mỗi tháng</small><b>${money(dep.monthly)}</b></div><div><small>Đã khấu hao</small><b>${money(dep.accumulated)}</b></div></div><div class="row" style="font-size:9px;margin-bottom:6px"><span class="sub">${dep.elapsed} / ${a.months} tháng</span><span class="push">Còn lại <b>${money(dep.remaining)}</b></span></div><div class="progress"><i style="width:${Math.min(100,dep.elapsed/Number(a.months)*100)}%"></i></div></section>`:`<section class="panel"><h3>Tồn kho vật tư</h3><div class="depreciation-metrics"><div><small>Số lượng</small><b>${num(D.stock[a.id]?.quantity)} ${esc(a.unit)}</b></div><div><small>Bình quân</small><b>${money(D.stock[a.id]?.average)}</b></div><div><small>Giá trị tồn</small><b>${money(D.stock[a.id]?.value)}</b></div></div></section>`}<section class="panel"><div class="panel-heading"><div><h3>Lịch sử</h3><small>Cấp phát, mượn trả, bảo trì, kiểm kê và thay đổi thông tin</small></div></div>${events.length?events.map(e=>e.html).join(''):'<div class="empty">Chưa có lịch sử</div>'}</section></div><div><section class="panel"><h3>Nơi để</h3><p class="page-sub">${esc(a.location||'Chưa có vị trí')}</p></section><section class="panel"><h3>Mã QR</h3><div class="qr-box">${qr(a.id)}<p>Quét bằng điện thoại để mở trang này</p></div><div class="qr-buttons"><button onclick="copyAssetLink('${a.id}')">${icon('copy')} Sao chép link</button><button onclick="printQR('${a.id}')">${icon('print')} In tem</button></div></section><section class="panel"><h3>Thao tác</h3><div class="action-list">${assetActions(a).map(([type,title])=>`<button onclick="transactionForm('${type}','${a.id}')">${boxIcon(actionIcons[type])}${title}<span class="chevron">${icon('chevron')}</span></button>`).join('')}${a.kind!=='VT'&&a.status!=='THANH_LY'?`<button onclick="maintenanceForm('${a.id}')">${boxIcon('tool')}Ghi bảo trì, sửa chữa<span class="chevron">${icon('chevron')}</span></button>`:''}</div></section><section class="panel"><h3>Ảnh</h3><div id="assetPhoto">${a.imageFileId?'<div class="loading" style="min-height:100px">Đang tải ảnh…</div>':`<div class="photo-empty">${icon('image')}Chưa có ảnh</div>`}</div><label class="sub" style="margin-top:10px">${a.imageFileId?'Thay ảnh':'Thêm ảnh'} · JPG/PNG/WebP, tối đa 5 MB<input type="file" accept="image/jpeg,image/png,image/webp" onchange="uploadAssetPhoto('${a.id}',this)"></label></section></div></div>`;
 if(a.imageFileId)call('getAssetPhoto',[a.id],src=>{if(page==='detail'&&selectedAsset===a.id&&$('assetPhoto')){const image=document.createElement('img');image.className='asset-photo';image.alt=a.name;image.src=src;$('assetPhoto').replaceChildren(image);}});
}
function changedFields(h){try{const before=JSON.parse(h.before),after=JSON.parse(h.after),fields={name:'Tên',price:'Giá mua',purchaseDate:'Ngày mua',purchaseTime:'Giờ mua',months:'Tháng khấu hao',location:'Vị trí',brand:'Thương hiệu',model:'Model',serial:'Serial',warrantyDate:'Bảo hành',nextMaintenance:'Bảo trì',note:'Ghi chú'};return Object.keys(fields).filter(k=>String(before[k]||'')!==String(after[k]||'')).map(k=>esc(fields[k])+': '+esc(before[k]||'—')+' → '+esc(after[k]||'—')).join('<br>')||'Cập nhật thông tin';}catch{return 'Cập nhật thông tin';}}
function assetLink(id){return D.appUrl?D.appUrl+'?asset='+encodeURIComponent(id):'';}
function qr(id){const link=assetLink(id);if(!link)return '<p class="sub">Chưa có URL Web App. Lưu URL /exec trong Cài đặt để tạo QR.</p>';if(typeof qrcode!=='function')return '<p class="sub">Chưa tải được thư viện QR.</p>';const q=qrcode(0,'M');q.addData(link);q.make();return q.createSvgTag(4,8);}
async function copyAssetLink(id){const link=assetLink(id);if(!link)return toast('Lưu URL Web App /exec trong Cài đặt trước.');try{await navigator.clipboard.writeText(link);toast('Đã sao chép liên kết tài sản');}catch{openForm('Liên kết tài sản',section('Sao chép liên kết',input('link','URL',link,'text','readonly')),null,'Đóng');$('submit').type='button';$('submit').onclick=closeForm;}}
function printQR(id){const a=D.assets.find(a=>a.id===id);if(!assetLink(id))return toast('Chưa có URL Web App để tạo tem QR');lastDocumentId='';showDocument({title:'Tem QR — '+a.code,html:`<!doctype html><html><meta charset="utf-8"><style>body{font:12px system-ui;text-align:center;padding:20px}svg{width:160px;height:160px}h3{margin:8px}</style><body><p>${esc(D.settings.businessName)}</p>${qr(id)}<h3>${esc(a.code)}</h3><p>${esc(a.name)}</p></body></html>`,url:''});}
async function uploadAssetPhoto(id,inputEl){const file=inputEl.files[0];if(!file)return;if(file.size>5*1024*1024)return toast('Ảnh tối đa 5 MB');const reader=new FileReader();reader.onload=async()=>{setBusy(true);try{const r=await rpc('uploadPhoto',[id,String(reader.result).split(',')[1],file.type]);D=r.data;setBusy(false);render();toast(r.message);}catch(e){reportError(e);}};reader.onerror=()=>toast('Không đọc được ảnh');reader.readAsDataURL(file);}
function issueView(){head('Cấp phát & Mượn trả','Lập phiếu, theo dõi người nhận và thời hạn trả',`<button onclick="transactionForm('CHO_MUON')">${icon('clock')} Cho mượn</button><button class="primary" onclick="transactionForm('CAP_PHAT')">${icon('plus')} Cấp phát</button>`);const types=['CAP_PHAT','DIEU_CHUYEN','CHO_MUON','TRA_MUON','THU_HOI','THANH_LY'];$('content').innerHTML=`<div class="tabs">${types.map(t=>`<button onclick="transactionForm('${t}')">${icon(actionIcons[t])}${actions[t]}</button>`).join('')}</div><section class="panel"><h3 style="margin-bottom:12px">Lịch sử phiếu</h3>${txTable(D.transactions.filter(t=>types.includes(t.type)).slice().reverse())}</section>`;}
function txTable(tx){return table(['Ngày','Loại phiếu','Tài sản','Người nhận / Bộ phận','Hạn trả','Giá trị / Thu hồi','Biên bản'],tx.map(t=>`<tr><td>${displayDate(t.date)}</td><td><span class="badge">${esc(actions[t.type]||t.type)}</span></td><td><button class="link" onclick="detail('${t.assetId}')">${esc(t.assetName)}</button><span class="code">${esc(t.assetCode)}</span></td><td>${esc(t.employeeName||'—')}<span class="code">${esc(t.department)}</span></td><td>${t.dueDate?displayDate(t.dueDate):'—'}</td><td>${money(t.amount)}</td><td><button class="link" onclick="documentFor('${t.requestId||t.id}')">${icon('file')} Mở biên bản</button></td></tr>`));}
function stockView(){const materials=D.assets.filter(a=>a.kind==='VT');head('Kho vật tư','Nhập – xuất – tồn · giá bình quân di động',`<button onclick="assetForm(null,'VT')">${icon('plus')} Sản phẩm</button><button onclick="transactionForm('XUAT_VT')">${icon('arrow')} Xuất dùng</button><button class="primary" onclick="transactionForm('NHAP_VT')">${icon('plus')} Nhập kho</button>`);$('content').innerHTML=`<div class="stats">${stat('Sản phẩm',materials.length,'Theo từng quy cách','box')}${stat('Giá trị tồn',compactMoney(Object.values(D.stock).reduce((s,a)=>s+a.value,0)),'Theo giá nhập / xuất','chart','green')}${stat('Hết tồn',materials.filter(a=>!D.stock[a.id]?.quantity).length,'Cần bổ sung','alert','red')}${stat('Dưới tồn tối thiểu',materials.filter(a=>Number(a.minStock)>0&&D.stock[a.id]?.quantity<Number(a.minStock)).length,'Theo mức đã khai báo','box','orange')}</div><section class="panel"><div class="filters"><div class="search-field">${icon('search')}<input placeholder="Tìm mã, tên sản phẩm…" aria-label="Tìm vật tư" oninput="stockFilter(this.value)"></div><button onclick="csvDownload('ton-kho',[['Mã','Tên','ĐVT','Tồn','Bình quân','Giá trị'],...D.assets.filter(a=>a.kind==='VT').map(a=>[a.code,a.name,a.unit,D.stock[a.id]?.quantity,D.stock[a.id]?.average,D.stock[a.id]?.value])])">${icon('download')} Xuất CSV</button></div><div id="stockTable">${stockTable(materials)}</div></section><section class="panel"><div class="panel-heading"><h3>Lịch sử nhập / xuất</h3></div>${txTable(D.transactions.filter(t=>['NHAP_VT','XUAT_VT'].includes(t.type)).slice().reverse())}</section>`;}
function stockTable(list){return table(['Sản phẩm','Nhóm','Đơn vị','Tồn kho','Tối thiểu','Đơn giá bình quân','Giá trị tồn',''],list.map(a=>`<tr><td><button class="link asset-name" onclick="detail('${a.id}')">${esc(a.name)}</button><span class="code">${esc(a.code)}</span></td><td>${esc((D.groups.find(g=>g.id===a.group)||{}).name)}</td><td>${esc(a.unit)}</td><td><span class="badge ${Number(D.stock[a.id]?.quantity)<=Number(a.minStock||0)?'red':'green'}">${num(D.stock[a.id]?.quantity)}</span></td><td>${num(a.minStock)}</td><td>${money(D.stock[a.id]?.average)}</td><td>${money(D.stock[a.id]?.value)}</td><td><button class="link" onclick="transactionForm('NHAP_VT','${a.id}')">Nhập</button> · <button class="link" onclick="transactionForm('XUAT_VT','${a.id}')">Xuất</button></td></tr>`));}
function stockFilter(q){$('stockTable').innerHTML=stockTable(D.assets.filter(a=>a.kind==='VT'&&[a.code,a.name].join(' ').toLocaleLowerCase('vi').includes(q.toLocaleLowerCase('vi'))));}
function auditView(){if(!D.audits.some(a=>a.id===auditSelected))auditSelected=D.audits.at(-1)?.id||'';const a=D.audits.find(a=>a.id===auditSelected),all=D.auditLines.filter(l=>l.auditId===auditSelected);head(a?a.name:'Kiểm kê','Đánh dấu tài sản thực tế và đối chiếu số liệu trên sổ',`<button class="desktop-only" onclick="auditForm()">${icon('plus')} Tạo đợt</button>${a?`<button class="desktop-only" onclick="auditExport(true)">${icon('download')} Xuất Excel</button><button class="desktop-only" onclick="documentFor('${a.id}')">${icon('print')} Biên bản</button><button class="primary desktop-only" onclick="closeAudit()" ${a.status==='DONG'?'disabled':''}>${icon('check')} Chốt đợt</button>`:''}`,'Quản lý / Kiểm kê');
 $('content').innerHTML=`<div class="audit-toolbar row"><select aria-label="Chọn đợt kiểm kê" style="max-width:350px" onchange="auditSelected=this.value;auditFilter='all';render()">${D.audits.map(a=>`<option value="${a.id}" ${a.id===auditSelected?'selected':''}>${esc(a.name)} · ${displayDate(a.date)} · ${a.status==='MO'?'Đang mở':'Đã chốt'}</option>`).join('')||'<option>Chưa có đợt kiểm kê</option>'}</select><button class="mobile-only primary" onclick="auditForm()" aria-label="Tạo đợt kiểm kê">${icon('plus')}</button>${a?`<label class="check desktop-only"><input type="checkbox" id="quickMark"> Áp dụng ngay khi chọn</label>`:''}</div><div class="audit-summary compact-hide">${stat('Tổng tài sản',all.length,'','box')}${stat('Đã kiểm',all.filter(l=>l.result!=='CHUA_KIEM').length,'','check','green')}${stat('Chưa kiểm',all.filter(l=>l.result==='CHUA_KIEM').length,'','clock','orange')}${stat('Có vấn đề',all.filter(l=>!['CHUA_KIEM','CO_MAT'].includes(l.result)).length,'','alert','red')}</div><div class="tabs">${[['pending','Chưa kiểm',all.filter(l=>l.result==='CHUA_KIEM').length],['issue','Có vấn đề',all.filter(l=>!['CHUA_KIEM','CO_MAT'].includes(l.result)).length],['all','Tất cả',all.length]].map(([id,title,n])=>`<button class="${auditFilter===id?'active':''}" onclick="auditFilter='${id}';renderAuditLines()">${title} <span class="count">${n}</span></button>`).join('')}</div><section class="panel audit-panel"><div class="search-field" style="margin:11px 0">${icon('search')}<input placeholder="Tìm mã, tên, vị trí, người dùng…" aria-label="Tìm trong kiểm kê" value="${esc(auditQuery)}" oninput="auditQuery=this.value;renderAuditLines()"></div>${a?.status==='MO'?'<button class="link" style="font-size:10px;margin:3px 0 8px" onclick="markVisiblePresent()">Đánh dấu chưa kiểm là Có mặt (danh sách đang lọc)</button>':''}<div id="auditLines"></div></section>${a?`<div class="mobile-only row"><button onclick="documentFor('${a.id}')">${icon('print')} Biên bản</button><button onclick="auditExport()">${icon('download')} Xuất CSV</button><button class="primary" onclick="closeAudit()" ${a.status==='DONG'?'disabled':''}>Chốt đợt</button></div>`:''}`;renderAuditLines();}
function auditVisible(){const q=auditQuery.toLocaleLowerCase('vi');return D.auditLines.filter(l=>l.auditId===auditSelected&&(!q||[l.assetCode,l.assetName,l.location,l.employeeName].join(' ').toLocaleLowerCase('vi').includes(q))&&(auditFilter==='all'||(auditFilter==='pending'?l.result==='CHUA_KIEM':!['CHUA_KIEM','CO_MAT'].includes(l.result)))).sort((l,r)=>Number(D.assets.find(a=>a.id===l.assetId)?.kind==='VT')-Number(D.assets.find(a=>a.id===r.assetId)?.kind==='VT'));}
function renderAuditLines(){const a=D.audits.find(a=>a.id===auditSelected),list=auditVisible();if(!$('auditLines'))return;document.querySelectorAll('.tabs button').forEach((b,i)=>{b.classList.toggle('active',['pending','issue','all'][i]===auditFilter);});$('auditLines').innerHTML=list.length?list.map(l=>`<div class="audit-item" id="audit-${l.id}"><div><div class="audit-title">${boxIcon('monitor')}<div><b>${esc(l.assetName)}</b><small>${esc(l.assetCode)} · ${esc(l.location)}${l.employeeName?' · '+esc(l.employeeName):''}</small><small>Theo sổ: ${num(l.expected)}${l.actual!==''?' · Thực tế: '+num(l.actual):''}</small></div></div><p class="audit-note">${esc(l.note)}</p></div><div class="audit-actions">${[['CO_MAT','Có mặt'],['THIEU','Thiếu'],['HONG','Hỏng'],['SAI_VI_TRI','Sai vị trí']].map(([r,title])=>`<button class="${l.result===r?'selected':''}" ${a?.status==='DONG'?'disabled':''} onclick="auditChoose('${l.id}','${r}')">${title}</button>`).join('')}</div>${a?.status==='MO'?`<div class="inline-controls wide"><input type="number" min="0" step="any" id="qty-${l.id}" value="${esc(l.actual===''?l.expected:l.actual)}" aria-label="Số lượng thực tế ${esc(l.assetName)}"><input id="note-${l.id}" value="${esc(l.note)}" placeholder="Ghi chú" aria-label="Ghi chú ${esc(l.assetName)}"><button class="save-line" onclick="saveAuditInline('${l.id}')">Lưu</button></div>`:''}</div>`).join(''):'<div class="empty">Không có mục trong danh sách này</div>';}
const auditDraft={};
function auditChoose(id,result){auditDraft[id]=result;const el=$('audit-'+id);el.querySelectorAll('.audit-actions button').forEach((b,i)=>b.classList.toggle('selected',['CO_MAT','THIEU','HONG','SAI_VI_TRI'][i]===result));if(result==='CO_MAT')$('qty-'+id).value=D.auditLines.find(l=>l.id===id).expected;if(result==='THIEU'&&Number($('qty-'+id).value)===Number(D.auditLines.find(l=>l.id===id).expected))$('qty-'+id).value=0;if($('quickMark')?.checked||window.matchMedia('(max-width:760px)').matches)saveAuditInline(id);}
async function saveAuditInline(id){const l=D.auditLines.find(l=>l.id===id),result=auditDraft[id]||(l.result==='CHUA_KIEM'?'CO_MAT':l.result);await send('saveAuditLine',{id,result,actual:$('qty-'+id).value,note:$('note-'+id).value},{preserveScroll:true});delete auditDraft[id];}
async function markVisiblePresent(){const lines=auditVisible().filter(l=>l.result==='CHUA_KIEM');if(!lines.length)return toast('Không có mục chưa kiểm');if(lines.length>200)return toast('Lọc phạm vi nhỏ hơn: tối đa 200 mục mỗi lần');if(!confirm('Xác nhận đã kiểm thực tế và có mặt đủ '+lines.length+' mục trong danh sách đang lọc?'))return;await send('markAuditPresent',{auditId:auditSelected,ids:lines.map(l=>l.id)});}
function closeAudit(){if(confirm('Chốt đợt kiểm kê? Kết quả đã chốt sẽ không chỉnh sửa được.'))send('closeAudit',{id:auditSelected});}
function auditExport(excel=false){const a=D.audits.find(a=>a.id===auditSelected);downloadData(excel,'kiem-ke-'+(a?.date||date()),[['Mã','Tên','Người giữ','Vị trí','Theo sổ','Thực tế','Kết quả','Ghi chú'],...D.auditLines.filter(l=>l.auditId===auditSelected).map(l=>[l.assetCode,l.assetName,l.employeeName,l.location,l.expected,l.actual,({CHUA_KIEM:'Chưa kiểm',CO_MAT:'Có mặt',THIEU:'Thiếu / lệch số lượng',HONG:'Hỏng',SAI_VI_TRI:'Sai vị trí'})[l.result],l.note])]);}
function reportView(){head('Báo cáo','Số liệu tổng hợp theo bộ phận, loại tài sản và vòng đời',`<input type="month" style="width:145px;padding:6px" aria-label="Tháng báo cáo" value="${esc(reportMonth||D.month)}" onchange="changeReportMonth(this.value)"><button onclick="exportReport(true)">${icon('download')} Xuất Excel</button><button class="desktop-only" onclick="exportReport()">CSV</button>`);const tabs=[['department','Theo bộ phận'],['type','Theo loại'],['depreciation','Khấu hao'],['maintenance','Chi phí bảo trì'],['warranty','Bảo hành']];$('content').innerHTML=`<div class="tabs">${tabs.map(([id,title])=>`<button class="${id===reportTab?'active':''}" onclick="reportTab='${id}';render()">${title}</button>`).join('')}</div><div id="reportBody"></div>`;renderReportBody();}
async function changeReportMonth(month){if(!month)return;try{const sequence=++requestSequence;const bundle=await rpc('getReportBundle',[month]);if(sequence!==requestSequence)return;reportMonth=month;D.report=bundle.report;reportAnalytics=bundle.analytics;render();}catch(e){reportError(e);}}
function reportFiltered(){return D.report.filter(a=>(!departmentFilter||a.department===departmentFilter)&&(!typeFilter||a.kind===typeFilter));}
function reportFilters(){return `<div class="filters"><div class="search-field">${icon('search')}<input placeholder="Tìm tài sản…" aria-label="Tìm báo cáo" oninput="reportSearch(this.value)"></div><select aria-label="Lọc loại báo cáo" onchange="typeFilter=this.value;renderReportBody()">${optionTags(D.types.filter(t=>t.id!=='VT').map(t=>[t.id,t.name]),typeFilter,'Tất cả loại')}</select><select aria-label="Lọc bộ phận báo cáo" onchange="departmentFilter=this.value;renderReportBody()">${optionTags(D.departments.map(t=>[t.name,t.name]),departmentFilter,'Mọi bộ phận')}</select></div>`;}
function renderReportBody(){const list=reportFiltered(),active=list.filter(a=>!a.disposed),price=active.reduce((s,a)=>s+Number(a.price),0),acc=active.reduce((s,a)=>s+a.accumulated,0),remaining=active.reduce((s,a)=>s+a.remaining,0);let html='';
 if(['department','type'].includes(reportTab)){const key=reportTab==='type'?'kind':'department',group={};active.forEach(a=>{const name=key==='kind'?typeName(a.kind):(a.department||'Chưa cấp / Trong kho');if(!group[name])group[name]={count:0,price:0,acc:0,remaining:0};group[name].count++;group[name].price+=Number(a.price);group[name].acc+=a.accumulated;group[name].remaining+=a.remaining;});const max=Math.max(1,...Object.values(group).map(g=>g.count));html=`<div class="stats">${stat('Tổng tài sản',active.length,'Chưa thanh lý','box')}${stat('Nguyên giá',compactMoney(price),'Tổng nguyên giá','chart')}${stat('Đã khấu hao',compactMoney(acc),'Lũy kế đến tháng chọn','clock','orange')}${stat('Còn lại',compactMoney(remaining),'Giá trị sổ quản lý','shield','green')}</div><section class="panel"><h3>Cơ cấu ${reportTab==='type'?'theo loại':'theo bộ phận'}</h3><div class="group-bars">${Object.entries(group).map(([name,g])=>`<div class="group-bar"><span>${esc(name)}</span><div class="mini-bar"><i style="width:${100*g.count/max}%"></i></div><span>${g.count} tài sản</span></div>`).join('')||'<div class="empty">Chưa có dữ liệu</div>'}</div></section><section class="panel"><h3 style="margin-bottom:12px">Chi tiết tổng hợp</h3>${table([reportTab==='type'?'Loại tài sản':'Bộ phận','Số lượng','Nguyên giá','Đã khấu hao','Giá trị còn lại'],Object.entries(group).map(([name,g])=>`<tr><td>${esc(name)}</td><td>${g.count}</td><td>${money(g.price)}</td><td>${money(g.acc)}</td><td>${money(g.remaining)}</td></tr>`))}</section>`;
 }else if(reportTab==='depreciation'){html=`<div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat('Nguyên giá',compactMoney(price),active.length+' tài sản','box')}${stat('Khấu hao lũy kế',compactMoney(acc),price?Math.round(acc/price*100)+'% nguyên giá':'','chart','orange')}${stat('Giá trị còn lại',compactMoney(remaining),price?Math.round(remaining/price*100)+'% nguyên giá':'','shield','green')}</div><div class="report-grid"><section class="panel"><h3>Lịch khấu hao theo năm</h3><small>Toàn bộ tài sản · tháng thanh lý vẫn tính đủ</small>${chart((reportAnalytics||D.analytics).annual,true)}</section><section class="panel"><h3>Tình trạng khấu hao</h3>${[['Đang khấu hao',active.filter(a=>a.remaining>0).length,'clock'],['Đã khấu hao hết',active.filter(a=>a.remaining===0).length,'check'],['Đã thanh lý',list.filter(a=>a.disposed).length,'trash']].map(([name,n,ic])=>`<div class="alert-row">${boxIcon(ic)}<span class="alert-text">${name}</span><b>${n}</b></div>`).join('')}<button class="link" style="margin-top:15px" onclick="send('exportDepreciation',{month:reportMonth||D.month})">${icon('file')} Xuất bảng sang Google Sheets</button></section></div><section class="panel">${reportFilters()}<div id="reportTable">${depreciationTable(list)}</div><p class="sub" style="margin-top:10px">Bộ phận là phân công hiện tại. Sửa ngày/giá mua sẽ tính lại lịch khấu hao.</p></section>`;
 }else if(reportTab==='maintenance'){const year=(reportMonth||D.month).slice(0,4),records=D.maintenance.filter(m=>m.date.startsWith(year)),total=records.reduce((s,m)=>s+Number(m.cost),0);html=`<div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat('Tổng chi phí '+year,compactMoney(total),'Chi phí đã ghi nhận','tool')}${stat('Lượt bảo trì',records.length,'Trong năm chọn','clipboard','blue')}${stat('Tài sản bảo trì',new Set(records.map(m=>m.assetId)).size,'Không tính vật tư','monitor','green')}</div><section class="panel"><h3>Chi phí bảo trì 12 tháng</h3>${chart(maintenanceBins(reportAnalytics||D.analytics))}</section><section class="panel">${table(['Ngày','Tài sản','Nội dung','Chi phí','Lịch tiếp theo',''],records.slice().reverse().map(m=>{const a=D.assets.find(a=>a.id===m.assetId)||{};return `<tr><td>${displayDate(m.date)}</td><td><button class="link" onclick="detail('${m.assetId}')">${esc(a.name)}</button><span class="code">${esc(a.code)}</span></td><td>${esc(m.content)}</td><td>${money(m.cost)}</td><td>${displayDate(m.nextDate)}</td><td><button class="link" onclick="documentFor('${m.requestId||m.id}')">Biên bản</button></td></tr>`;}))}</section>`;
 }else{const a=D.assets.filter(a=>a.kind!=='VT'&&a.status!=='THANH_LY'),exp=a.filter(a=>a.warrantyDate&&a.warrantyDate<D.today),soon=(D.alerts||[]).filter(x=>x.type==='warranty');html=`<div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat('Còn bảo hành',a.filter(a=>a.warrantyDate>=D.today).length,'Theo ngày hiện tại','shield','green')}${stat('Sắp hết hạn',soon.length,'Trong '+D.settings.reminderDays+' ngày','clock','orange')}${stat('Đã hết hạn',exp.length,'Cần kiểm tra','alert','red')}</div><section class="panel">${table(['Tài sản','Ngày mua','Hết bảo hành','Người giữ','Trạng thái'],a.map(a=>`<tr><td><button class="link asset-name" onclick="detail('${a.id}')">${esc(a.name)}</button><span class="code">${esc(a.code)}</span></td><td>${displayDate(a.purchaseDate)}</td><td>${displayDate(a.warrantyDate)}</td><td>${esc(employee(a.employeeId)||'—')}</td><td><span class="badge ${a.warrantyDate?(a.warrantyDate<D.today?'red':'green'):''}">${a.warrantyDate?(a.warrantyDate<D.today?'Đã hết hạn':'Còn bảo hành'):'Chưa khai báo'}</span></td></tr>`))}</section><p class="sub">Bảo hành tính theo ngày hiện tại, không theo tháng khấu hao đang chọn.</p>`;}
 $('reportBody').innerHTML=html;}
function depreciationTable(list){return table(['Tài sản','Ngày mua','Nguyên giá','Tháng KH','KH mỗi tháng','Đã khấu hao','Còn lại','Tiến độ'],list.map(a=>`<tr><td><button class="link asset-name" onclick="detail('${a.id}')">${esc(a.name)}</button><span class="code">${esc(a.code)}${a.disposed?' · Đã thanh lý':''}</span></td><td>${displayDate(a.purchaseDate)}</td><td>${money(a.price)}</td><td>${a.months}</td><td>${money(a.monthly)}</td><td>${money(a.accumulated)}</td><td>${money(a.remaining)}</td><td><div class="mini-bar"><i style="width:${Number(a.price)?100*a.accumulated/Number(a.price):0}%"></i></div></td></tr>`));}
function reportSearch(q){$('reportTable').innerHTML=depreciationTable(reportFiltered().filter(a=>[a.code,a.name].join(' ').toLocaleLowerCase('vi').includes(q.toLocaleLowerCase('vi'))));}
function employeesView(){head('Nhân viên','Thông tin người sử dụng và bộ phận nhận tài sản',`<button class="primary" onclick="employeeForm()">${icon('plus')} Thêm nhân viên</button>`);$('content').innerHTML=`<section class="panel">${table(['Nhân viên','Bộ phận','Vị trí','Email','Tài sản đang giữ','Trạng thái',''],D.employees.map(e=>`<tr><td><div class="asset-cell">${boxIcon('user')}<div><b>${esc(e.name)}</b><span class="code">${esc(e.id)}</span></div></div></td><td>${esc(e.department)}</td><td>${esc(e.location)}</td><td>${esc(e.email||'Chưa có')}</td><td>${D.assets.filter(a=>a.employeeId===e.id&&a.status!=='THANH_LY').length}</td><td><span class="badge ${e.active==='true'?'green':''}">${e.active==='true'?'Đang làm việc':'Ngừng làm'}</span></td><td><button class="link" onclick="employeeForm('${e.id}')">${icon('edit')} Sửa</button></td></tr>`))}</section><p class="sub">Nhân viên là người nhận tài sản, chưa phải tài khoản đăng nhập ứng dụng.</p>`;}
function catalogView(){const tabs=[['types','Loại tài sản','LoaiTaiSan'],['groups','Nhóm vật tư','NhomSanPham'],['departments','Bộ phận','PhongBan'],['locations','Vị trí','ViTri'],['suppliers','Nhà cung cấp','NhaCungCap']],selected=tabs.find(t=>t[0]===catalogTab)||tabs[0],data=D[selected[0]];head('Danh mục','Tự mở rộng loại tài sản, vật tư và thông tin cơ sở',`<button class="primary" onclick="categoryForm('${selected[2]}')">${icon('plus')} Thêm ${selected[1].toLowerCase()}</button>`);$('content').innerHTML=`<div class="tabs">${tabs.map(([id,title])=>`<button class="${id===catalogTab?'active':''}" onclick="catalogTab='${id}';render()">${title}</button>`).join('')}</div><section class="panel">${table(['Tên',...(['types','groups'].includes(catalogTab)?['Tiền tố mã']:[])],data.map(r=>`<tr><td>${esc(r.name)}</td>${r.prefix?'<td><span class="badge">'+esc(r.prefix)+'</span></td>':''}</tr>`))}</section><p class="sub">Mã đã cấp không đổi khi điều chỉnh thông tin. Loại mới quản lý theo từng chiếc; sản phẩm tiêu hao đặt trong loại Vật tư.</p>`;}
function settingsView(){const c=D.settings;head('Cài đặt','Tùy chỉnh hộ kinh doanh, email và lưu biên bản',`<button class="primary" onclick="settingsSubmit()">${icon('check')} Lưu cài đặt</button>`);$('content').innerHTML=`<form id="settingsForm" onsubmit="event.preventDefault();settingsSubmit()"><div class="settings-layout"><div><section class="panel settings-card"><div class="panel-heading"><div><h3>Thông tin cơ sở</h3><small>Hiển thị trên biên bản và ứng dụng</small></div></div>${input('businessName','Tên hộ kinh doanh',c.businessName,'text','required')}${input('address','Địa chỉ',c.address)}${input('webAppUrl','URL Web App /exec',c.webAppUrl||D.appUrl,'url','placeholder="https://script.google.com/macros/s/.../exec"')}<p class="sub">QR mở trực tiếp trang tài sản. Chỉ tài khoản được phép truy cập Web App mới xem được.</p></section><section class="panel settings-card"><h3 style="margin-bottom:12px">Lưu biên bản vào Google Drive</h3>${checkbox('autoSavePdf','Tự lưu PDF mỗi khi lập biên bản (cấp phát, thu hồi, điều chuyển, mượn trả, bảo trì, thanh lý)',c.autoSavePdf==='true')}<p class="sub">PDF lưu trong Drive của chủ sở hữu, đường dẫn ghi cùng phiếu. Không tự chia sẻ công khai.</p></section></div><section class="panel settings-card"><div class="panel-heading"><div><h3>Email nhắc hạn</h3><small>Mượn quá hạn, lịch bảo trì, sắp hết bảo hành. Không có việc thì không gửi.</small></div></div>${checkbox('remindersEnabled','Gửi email nhắc hằng ngày',c.remindersEnabled==='true')}${select('reminderHour','Giờ gửi',Array.from({length:24},(_,i)=>[String(i),i+' giờ']),c.reminderHour)}${input('reminderDays','Nhắc trước bao nhiêu ngày',c.reminderDays,'number','min="0" max="365" step="1"')}${input('reminderEmail','Email nhận (phân cách bằng dấu phẩy)',c.reminderEmail,'text','placeholder="ketoan@example.com, kho@example.com"')}<p class="sub">Google có thể gửi trong khoảng giờ đã chọn, theo giờ Việt Nam. Cần cấp quyền khi bật lịch lần đầu.</p>${checkbox('notifyAssignees','Gửi thêm email riêng tới từng người giữ tài sản liên quan',c.notifyAssignees==='true')}${checkbox('copyOwner','Gửi cho chính tôi (chủ sở hữu ứng dụng)',c.copyOwner==='true')}<p class="sub">Mỗi địa chỉ nhận tối đa một lần/ngày. Nhân viên chỉ nhận các việc liên quan đến tài sản của họ.</p></section></div></form>`;}
function section(title,content){return `<section class="form-section"><h3>${title}</h3><div class="form-grid">${content}</div></section>`;}
function input(name,label,value='',type='text',extra=''){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(name,label,items,value='',extra=''){return `<label>${esc(label)}<select name="${name}" ${extra}>${items.map(x=>`<option value="${esc(x[0])}" ${String(value)===String(x[0])?'selected':''}>${esc(x[1])}</option>`).join('')}</select></label>`;}
function note(name,label,value=''){return `<label class="wide">${esc(label)}<textarea name="${name}">${esc(value)}</textarea></label>`;}
function checkbox(name,label,checked=false){return `<label class="check wide"><input type="checkbox" name="${name}" ${checked?'checked':''}>${esc(label)}</label>`;}
function datalistInput(name,label,value,items){const id='list-'+name;return `<label>${esc(label)}<input name="${name}" value="${esc(value||'')}" list="${id}"><datalist id="${id}">${items.map(x=>`<option value="${esc(x.name)}"></option>`).join('')}</datalist></label>`;}
function openForm(title,html,handler,submitLabel='Lưu',subtitle=''){if($('modal').open)$('modal').close();$('modalTitle').textContent=title;$('modalSub').textContent=subtitle;$('fields').innerHTML=html;$('formError').style.display='none';$('form').dataset.requestId=requestId();$('submit').textContent=submitLabel;$('submit').className='primary';$('submit').type='submit';$('submit').onclick=null;$('form').onsubmit=e=>{e.preventDefault();if(busy)return;const p=Object.fromEntries(new FormData(e.target));handler?.(p,e.target);};$('modal').showModal();}
function closeForm(){if(!busy)$('modal').close();}
function requestId(){return 'req_'+Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');}
async function send(action,p,options={}){if(busy)return;setBusy(true);p.requestId=p.requestId||($('modal').open?$('form').dataset.requestId:requestId());try{const r=await rpc('mutate',[action,p]);D=r.data;reportMonth=D.month;reportAnalytics=null;setBusy(false);$('modal').close();if(action==='createAudit')auditSelected=D.audits.at(-1)?.id||'';render();toast(r.message);if(options.openDocument&&r.documentId)await documentFor(r.documentId);return r;}catch(e){reportError(e);return null;}}
function assetForm(id,kind){const a=D.assets.find(a=>a.id===id)||{};openForm(id?'Sửa tài sản':'Thêm tài sản',section('Thông tin chung',input('name','Tên tài sản / sản phẩm *',a.name,'text','required')+select('kind','Loại tài sản *',D.types.map(t=>[t.id,t.name]),a.kind||kind||'MI')+input('codePreview','Mã tài sản',a.code||'Tự gợi ý theo loại','text','readonly')+select('group','Nhóm vật tư',D.groups.map(g=>[g.id,g.name]),a.group)+input('brand','Thương hiệu',a.brand)+input('model','Model',a.model)+input('serial','Số serial',a.serial)+input('unit','Đơn vị tính *',a.unit||'Cái','text','required'))+section('Mua sắm và khấu hao',input('purchaseDate','Ngày mua *',a.purchaseDate||date(),'date','required')+input('purchaseTime','Giờ mua',a.purchaseTime||'09:00','time')+datalistInput('supplier','Nhà cung cấp',a.supplier,D.suppliers)+input('price','Nguyên giá / đơn giá tham khảo (đ) *',a.price??0,'number','min="0" step="any" required')+input('months','Khấu hao (tháng)',a.months||36,'number','min="1" step="1"')+input('warrantyDate','Hạn bảo hành',a.warrantyDate,'date')+input('nextMaintenance','Bảo trì tiếp theo',a.nextMaintenance,'date')+input('minStock','Tồn tối thiểu (vật tư)',a.minStock||0,'number','min="0" step="any"'))+section('Nơi để và ghi chú',datalistInput('location','Vị trí',a.location||'Kho chính',D.locations)+note('note','Ghi chú',a.note)+'<p class="help wide">Vật tư: tạo sản phẩm trước rồi nhập số lượng ở Kho vật tư. Tài sản: quản lý theo từng chiếc. Giá/ngày mua chỉnh sửa được; khấu hao tính lại theo dữ liệu mới.</p>'),p=>{if(id)p.kind=a.kind;delete p.codePreview;send('saveAsset',{...p,id});},'Lưu tài sản',id?a.code:'Mã được tạo tự động, không trùng');if(id)$('form').elements.kind.disabled=true;else{let sequence=0;const preview=async()=>{const seq=++sequence;try{const code=await rpc('nextAssetCode',[$('form').elements.kind.value,$('form').elements.group.value]);if(seq===sequence&&$('modal').open&&$('form').elements.codePreview)$('form').elements.codePreview.value=code;}catch{}};$('form').elements.kind.onchange=preview;$('form').elements.group.onchange=preview;preview();}}
function transactionForm(type,preselect){const material=['NHAP_VT','XUAT_VT'].includes(type),allowed={CAP_PHAT:['TRONG_KHO'],DIEU_CHUYEN:['DANG_DUNG'],THU_HOI:['DANG_DUNG'],CHO_MUON:['TRONG_KHO'],TRA_MUON:['DANG_MUON'],SUA_CHUA:['TRONG_KHO','DANG_DUNG','HONG'],HOAN_TAT_SUA:['DANG_SUA'],BAO_HONG:['TRONG_KHO','DANG_DUNG','DANG_MUON'],BAO_MAT:['TRONG_KHO','DANG_DUNG','DANG_MUON','HONG'],THANH_LY:['TRONG_KHO','DANG_DUNG','HONG','THAT_LAC','DANG_SUA']},available=D.assets.filter(a=>material?a.kind==='VT':a.kind!=='VT'&&(allowed[type]||[]).includes(a.status));
 const choices=material?select('assetId','Sản phẩm *',available.map(a=>[a.id,a.code+' · '+a.name+' · Tồn '+num(D.stock[a.id]?.quantity)]),preselect):`<div class="selector wide"><div class="search-field">${icon('search')}<input type="search" placeholder="Tìm mã, tên, người dùng, vị trí" aria-label="Tìm tài sản chọn phiếu" oninput="filterChoices(this.value)"></div><div class="asset-options">${available.map(a=>`<label class="select-asset" data-search="${esc([a.code,a.name,a.location,employee(a.employeeId)].join(' ').toLocaleLowerCase('vi'))}"><input type="checkbox" name="assetIds" value="${a.id}" ${a.id===preselect?'checked':''} onchange="selectionChanged('${type}')"><span class="select-title">${esc(a.name)}<small>${esc(a.code)} · ${esc(a.location)}</small></span>${statusBadge(a.status)}</label>`).join('')||'<div class="empty">Không có tài sản phù hợp</div>'}</div><div class="selection-footer"><span id="selectionCount">Đã chọn ${preselect?1:0} / ${available.length}</span><div class="row"><button type="button" onclick="selectAllChoices(true,'${type}')">Chọn hết</button><button type="button" onclick="selectAllChoices(false,'${type}')">Bỏ chọn</button></div></div></div>`;
 let html=section(material?'Vật tư':'Tài sản '+(['CAP_PHAT','CHO_MUON'].includes(type)?'trong kho':'cần '+actions[type].toLocaleLowerCase('vi')),choices);
 if(['CAP_PHAT','DIEU_CHUYEN','CHO_MUON'].includes(type))html+=section('Giao cho',select('employeeId','Người nhận',[['','Chọn nhân viên (có thể giao bộ phận)'],...D.employees.filter(e=>e.active==='true').map(e=>[e.id,e.name+' ('+e.id.slice(0,8)+')'])])+datalistInput('department','Bộ phận nhận','',D.departments)+datalistInput('location','Vị trí đặt','',D.locations)+'<p class="help wide">Tự lấy theo người nhận. Để trống người nhận và chọn bộ phận để giao cho bộ phận.</p>');
 let fields=input('date',type==='THANH_LY'?'Ngày thanh lý *':'Ngày *',date(),'date','required');
 if(type==='THANH_LY')fields+=select('method','Hình thức',[['BAN_LAI','Bán lại'],['HUY','Hủy'],['CHO_TANG','Cho tặng']]);
 if(type==='CHO_MUON')fields+=input('dueDate','Hạn trả *',date(),'date','required');
 if(!material&&type!=='THANH_LY')fields+=input('condition','Tình trạng khi giao / nhận','Tốt');
 if(['THU_HOI','TRA_MUON'].includes(type))fields+=datalistInput('location','Kho nhận','Kho chính',D.locations);
 if(material)fields+=input('quantity','Số lượng *',1,'number','min="0.000001" step="any" required')+(type==='NHAP_VT'?input('unitPrice','Đơn giá nhập (đ) *',0,'number','min="0" step="any" required'):'<p class="help">Giá xuất tự tính theo bình quân di động. Không cho phép xuất âm kho.</p>');
 fields+=input('reason','Lý do'+(type==='THANH_LY'?' *':''),'','text',type==='THANH_LY'?'required':'');
 if(type==='THANH_LY')fields+=input('amount','Giá thu hồi mỗi tài sản (đ) *',0,'number','min="0" step="any" required')+'<div id="salePreview" class="notice sale-preview wide">Chọn tài sản để xem giá trị còn lại và lãi/lỗ.</div>'+input('approver','Người duyệt')+input('decision','Số quyết định');
 else fields+=input('giver','Người giao');
 fields+=note('note','Ghi chú');html+=section(type==='THANH_LY'?'Thanh lý':'Phiếu',fields);html+=section('Biên bản',checkbox('openDocument','Mở biên bản để in sau khi lưu',true)+checkbox('savePdf','Lưu PDF vào Drive sau khi ghi phiếu',D.settings.autoSavePdf==='true'));
 openForm(actions[type],html,(p,form)=>{p.assetIds=material?[p.assetId]:new FormData(form).getAll('assetIds');p.type=type;p.savePdf=form.elements.savePdf.checked?'true':'false';send('transaction',p,{openDocument:form.elements.openDocument.checked});},actions[type],material?'Nhập – xuất – tồn vật tư':'Chọn một hoặc nhiều tài sản để lập cùng một phiếu');
 if(type==='THANH_LY'){$('submit').className='danger';['date','amount'].forEach(k=>$('form').elements[k].addEventListener('input',refreshSalePreview));refreshSalePreview();}
 if(['CAP_PHAT','DIEU_CHUYEN','CHO_MUON'].includes(type))$('form').elements.employeeId.onchange=e=>{const emp=D.employees.find(x=>x.id===e.target.value);if(emp){$('form').elements.department.value=emp.department;$('form').elements.location.value=emp.location;}};
 if(material&&type==='NHAP_VT'){const update=()=>{const a=D.assets.find(a=>a.id===$('form').elements.assetId.value);$('form').elements.unitPrice.value=a?.price||0;};$('form').elements.assetId.onchange=update;update();}
}
function filterChoices(q){q=q.toLocaleLowerCase('vi');document.querySelectorAll('.select-asset').forEach(el=>el.hidden=!el.dataset.search.includes(q));}
function selectAllChoices(checked,type){document.querySelectorAll('.select-asset:not([hidden]) input').forEach(i=>i.checked=checked);selectionChanged(type);}
function selectionChanged(type){const all=[...document.querySelectorAll('[name=assetIds]')];if($('selectionCount'))$('selectionCount').textContent='Đã chọn '+all.filter(i=>i.checked).length+' / '+all.length;if(type==='THANH_LY')refreshSalePreview();}
async function refreshSalePreview(){const ids=[...document.querySelectorAll('[name=assetIds]:checked')].map(i=>i.value),el=$('salePreview');if(!el)return;const seq=++saleSequence;if(!ids.length){el.textContent='Chọn tài sản để xem giá trị còn lại và lãi/lỗ.';return;}try{const r=await rpc('getSalePreview',[ids,$('form').elements.date.value,$('form').elements.amount.value]);if(seq!==saleSequence||!$('salePreview'))return;$('salePreview').innerHTML=`Giá trị còn lại tại ${displayDate($('form').elements.date.value)}: <strong>${money(r.bookValue)}</strong> (${ids.length} tài sản)<br>Thu hồi: ${money(r.proceeds)}<br><span style="color:${r.gainLoss<0?'var(--red)':'var(--green)'}">Lãi / lỗ: <strong>${money(r.gainLoss)}</strong></span>`;}catch(e){if(seq===saleSequence&&$('salePreview'))$('salePreview').textContent=e.message||String(e);}}
function maintenanceForm(assetId){openForm('Ghi bảo trì, sửa chữa',section('Tài sản',select('assetId','Tài sản *',D.assets.filter(a=>a.kind!=='VT'&&a.status!=='THANH_LY').map(a=>[a.id,a.code+' · '+a.name]),assetId))+section('Thông tin thực hiện',input('date','Ngày thực hiện *',date(),'date','required')+input('cost','Chi phí (đ) *',0,'number','min="0" step="any" required')+input('nextDate','Bảo trì tiếp theo','','date')+note('content','Nội dung *'))+section('Biên bản',checkbox('openDocument','Mở biên bản sau khi lưu',true)+checkbox('savePdf','Lưu PDF vào Drive',D.settings.autoSavePdf==='true')),(p,form)=>{p.savePdf=form.elements.savePdf.checked?'true':'false';send('maintenance',p,{openDocument:form.elements.openDocument.checked});},'Lưu bảo trì');}
function employeeForm(id){const e=D.employees.find(e=>e.id===id)||{};openForm(id?'Sửa nhân viên':'Thêm nhân viên',section('Thông tin nhân viên',input('name','Họ tên *',e.name,'text','required')+input('email','Email',e.email,'email')+datalistInput('department','Bộ phận',e.department,D.departments)+datalistInput('location','Vị trí làm việc',e.location,D.locations)+select('active','Trạng thái',[['true','Đang làm việc'],['false','Ngừng làm']],e.active||'true')),p=>send('saveEmployee',{...p,id}),'Lưu nhân viên');}
function categoryForm(tableName){openForm('Thêm danh mục',section('Thông tin',input('name','Tên *','','text','required')+(['LoaiTaiSan','NhomSanPham'].includes(tableName)?input('prefix','Tiền tố mã *','','text','required pattern="[A-Za-z][A-Za-z0-9]{1,7}"'):'')),p=>send('addCategory',{...p,table:tableName}),'Thêm danh mục');}
function auditForm(){openForm('Tạo đợt kiểm kê',section('Thông tin đợt',input('name','Tên đợt *','Kiểm kê tháng '+date().slice(0,7),'text','required')+input('date','Ngày kiểm kê *',date(),'date','required')+select('department','Phạm vi bộ phận',[['','Tất cả bộ phận'],...D.departments.map(d=>[d.name,d.name])])+select('location','Phạm vi vị trí',[['','Tất cả vị trí'],...D.locations.map(d=>[d.name,d.name])])+'<p class="help wide">Số lượng, người giữ và vị trí được chụp tại thời điểm tạo đợt. Kết quả kiểm kê không tự sửa tồn kho.</p>'),p=>send('createAudit',p),'Tạo đợt kiểm kê');}
function settingsSubmit(){const form=$('settingsForm');if(!form.reportValidity())return;const p=Object.fromEntries(new FormData(form));['remindersEnabled','notifyAssignees','copyOwner','autoSavePdf'].forEach(k=>p[k]=form.elements[k].checked?'true':'false');send('settings',p);}
async function documentFor(id){try{const r=await rpc('createDocument',[id,false]);lastDocumentId=id;showDocument(r);}catch(e){reportError(e);}}
function showDocument(d){lastDocumentHtml=d.html;$('documentTitle').textContent=d.title;$('docFrame').srcdoc=d.html;$('documentLink').textContent=d.url?'Mở PDF trên Drive':'';if(d.url)$('documentLink').href=d.url;else $('documentLink').removeAttribute('href');$('saveDrive').disabled=!lastDocumentId;$('documentDialog').showModal();}
function printDocument(){const iframe=$('docFrame');try{iframe.contentWindow.focus();iframe.contentWindow.print();}catch{toast('Trình duyệt chặn in. Chọn Lưu vào Google Drive rồi mở PDF để in.');}}
async function saveDocumentDrive(){if(!lastDocumentId)return;const button=$('saveDrive');button.disabled=true;try{const d=await rpc('createDocument',[lastDocumentId,true]);$('documentLink').href=d.url;$('documentLink').textContent='Mở PDF trên Drive';toast('Đã lưu PDF trên Drive');}catch(e){reportError(e);}finally{button.disabled=false;}}
async function downloadData(excel,title,data){if(!excel)return csvDownload(title,data);setBusy(true);try{const r=await rpc('exportExcel',[title,data]);setBusy(false);openForm('Xuất Excel',section('Báo cáo đã sẵn sàng',`<div class="wide"><p>Bản báo cáo riêng tư đã được tạo trong Google Drive của bạn.</p><p><a href="${esc(r.url)}" target="_blank" rel="noopener">${icon('download')} Tải file Excel (.xlsx)</a></p><p><a href="${esc(r.sheetUrl)}" target="_blank" rel="noopener">Mở bản báo cáo trong Google Sheets</a></p><p class="sub">Nếu trình duyệt chặn tải, mở bản Google Sheets rồi chọn Tệp → Tải xuống → Microsoft Excel.</p></div>`),()=>closeForm(),'Đóng');}catch(e){reportError(e);}}
function csvDownload(filename,data){const csv='\ufeff'+data.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportAssets(excel=false){downloadData(excel,'tai-san',[['Mã','Tên','Loại','Người giữ','Bộ phận','Vị trí','Ngày mua','Giờ mua','Giá mua','Trạng thái'],...filteredAssets().map(a=>[a.code,a.name,typeName(a.kind),employee(a.employeeId),a.department,a.location,a.purchaseDate,a.purchaseTime,a.price,names[a.status]])]);}
function exportReport(excel=false){if(reportTab==='maintenance'){const y=(reportMonth||D.month).slice(0,4);return downloadData(excel,'bao-tri-'+y,[['Ngày','Mã tài sản','Nội dung','Chi phí','Lịch tiếp theo'],...D.maintenance.filter(m=>m.date.startsWith(y)).map(m=>[m.date,(D.assets.find(a=>a.id===m.assetId)||{}).code,m.content,m.cost,m.nextDate])]);}if(reportTab==='warranty')return downloadData(excel,'bao-hanh',[['Mã','Tên','Ngày mua','Hết bảo hành','Người giữ'],...D.assets.filter(a=>a.kind!=='VT').map(a=>[a.code,a.name,a.purchaseDate,a.warrantyDate,employee(a.employeeId)])]);downloadData(excel,'bao-cao-'+(reportMonth||D.month),[['Mã','Tên','Loại','Bộ phận hiện tại','Tháng','Nguyên giá','Khấu hao/tháng','Lũy kế','Còn lại','Đã thanh lý'],...reportFiltered().map(a=>[a.code,a.name,typeName(a.kind),a.department,reportMonth||D.month,a.price,a.monthly,a.accumulated,a.remaining,a.disposed?'Có':'Không'])]);}
$('searchForm').onsubmit=e=>{e.preventDefault();assetQuery=$('globalSearch').value;assetStatus='';typeFilter='';departmentFilter='';locationFilter='';go('assets');};
function boot(){
  if(typeof google==='undefined'||!google.script){$('content').innerHTML='<div class="panel"><h2>Mở ứng dụng qua URL Web App</h2><p>Chạy setup rồi triển khai ứng dụng web trong Google Apps Script.</p></div>';return;}
  // URL parameters are optional; they must never prevent the data request.
  load();
  try{if(google.script.url&&typeof google.script.url.getLocation==='function')google.script.url.getLocation(loc=>{const id=loc&&loc.parameter&&loc.parameter.asset;if(!id)return;if(D){selectedAsset=id;go('detail');}else afterLoadAsset=id;});}catch(e){console.warn('Không đọc được tham số URL; dữ liệu vẫn được tải.');}
}
boot();
